 "content": "def transform(grid):
    """Expand a centered 2 into a downward V and add diagonal 1-stripes."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]

    # The 2 forms the two sides of a V, widening one cell on each side per row.
    for r in range(n):
        left = center - r
        right = center + r
        if 0 <= left < n:
            out[r][left] = 2
        if 0 <= right < n:
            out[r][right] = 2

    # Add 1s on every fourth descending diagonal, phased by the input marker.
    phase = (-center) % 4
    for r in range(3, n):
        for c in range(n):
            if (r - c) % 4 == phase and out[r][c] == 0:
                out[r][c] = 1
    return out

if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
